2173	
2174				if err != nil {
2175					return vmi.Status.Phase, err
2176				}
2177				if !isInitialized {
2178					c.queue.AddAfter(controller.VirtualMachineInstanceKey(vmi), time.Second*1)
2179					return vmi.Status.Phase, err
2180				} else if isUnresponsive {
2181					// virt-launcher is gone and VirtualMachineInstance never transitioned
2182					// from scheduled to Running.
2183					return v1.Failed, nil
2184				}
2185				return v1.Scheduled, nil
2186			case !vmi.IsRunning() && !vmi.IsFinal():
2187				return v1.Scheduled, nil
2188			case !vmi.IsFinal():
2189				// That is unexpected. We should not be able to delete a VirtualMachineInstance before we stop it.
2190				// However, if someone directly interacts with libvirt it is possible
2191				return v1.Failed, nil
2192			}
2193		} else {
2194			switch domain.Status.Status {
2195			case api.Shutoff, api.Crashed:
2196				switch domain.Status.Reason {
2197				case api.ReasonCrashed, api.ReasonPanicked:
2198					return v1.Failed, nil
2199				case api.ReasonDestroyed:
2200					if isACPIEnabled(vmi, domain) {
2201						// When ACPI is available, the domain was tried to be shutdown,
2202						// and destroyed means that the domain was destroyed after the graceperiod expired.
2203						// Without ACPI a destroyed domain is ok.
2204						return v1.Failed, nil
2205					}
2206					if vmi.Status.MigrationState != nil && vmi.Status.MigrationState.Failed && vmi.Status.MigrationState.Mode == v1.MigrationPostCopy {
2207						// A VMI that failed a post-copy migration should never succeed
2208						return v1.Failed, nil
2209					}
2210					return v1.Succeeded, nil
2211				case api.ReasonShutdown, api.ReasonSaved, api.ReasonFromSnapshot:
2212					return v1.Succeeded, nil
2213				case api.ReasonMigrated:
2214					// if the domain migrated, we no longer know the phase.
2215					return vmi.Status.Phase, nil
2216				}
2217			case api.Paused:
2218				switch domain.Status.Reason {
2219				case api.ReasonPausedPostcopyFailed:
2220					return v1.Failed, nil
2221				default:
2222					return v1.Running, nil
2223				}
2224			case api.Running, api.Blocked, api.PMSuspended:
2225				return v1.Running, nil
2226			}
2227		}
2228		return vmi.Status.Phase, nil
2229	}
