func migrationTargetPodDownOrMigrationFailed(vmi *virtv1.VirtualMachineInstance, pod *k8sv1.Pod) bool {
	if !vmi.IsMigrationTarget() {
		return false
	}
	if pod != nil && controller.PodIsDown(pod) {
		return true
	}
	return vmi.Status.MigrationState != nil &&
