// addMigrationStateFieldPatches appends JSON Patch operations for each field of the
// VMI MigrationState that changed between origMS and newMS. Fields that transition
// from a zero to a non-zero value produce an "add" operation at
// "/status/migrationState/<fieldName>", while fields that transition between two
// different non-zero values produce a "test" (asserting the previous value) followed
// by a "replace" (setting the new value). Unchanged fields are skipped. If newMS is
// nil the entire migrationState is removed via a "test" + "remove".
func addMigrationStateFieldPatches(patchSet *patch.PatchSet, origMS, newMS *virtv1.VirtualMachineInstanceMigrationState) {
	const basePath = "/status/migrationState"

	if newMS == nil {
		if origMS != nil {
			patchSet.AddOption(
				patch.WithTest(basePath, origMS),
				patch.WithRemove(basePath),
			)
		}
		return
	}

	if origMS == nil {
		origMS = &virtv1.VirtualMachineInstanceMigrationState{}
	}

	origValue := reflect.ValueOf(*origMS)
	newValue := reflect.ValueOf(*newMS)
	msType := origValue.Type()

	for i := 0; i < msType.NumField(); i++ {
		jsonName := strings.Split(msType.Field(i).Tag.Get("json"), ",")[0]
		if jsonName == "" || jsonName == "-" {
			continue
		}

		origField := origValue.Field(i)
		newField := newValue.Field(i)
		if reflect.DeepEqual(origField.Interface(), newField.Interface()) {
			// Unchanged field, nothing to patch.
			continue
		}

		fieldPath := fmt.Sprintf("%s/%s", basePath, jsonName)
		if origField.IsZero() {
			// zero -> non-zero
			patchSet.AddOption(patch.WithAdd(fieldPath, newField.Interface()))
		} else if !newField.IsZero() {
			// non-zero -> different non-zero
			patchSet.AddOption(
				patch.WithTest(fieldPath, origField.Interface()),
				patch.WithReplace(fieldPath, newField.Interface()),
			)
		}
	}
}

